object Instruction {
  type Decoder = RawInstruction => Either[InstructionDecodeError, Instruction]

  enum Definition(
      val opcode: SPIRVOpcode,
      val opcodeNumber: SPIRVOpcodeNumber,
      decode: Definition => Decoder,
      val meta: Metadata
  ) {
    case Nop extends Definition(
          SPIRVOpcode.assume("OpNop"),
          SPIRVOpcodeNumber.assume(0),
          definition => raw => Instruction.decodeDefinition(definition, raw, _ => Instruction.Nop()),
          Metadata("Miscellaneous".assume[MinLength[1] & NoNul], Some("1.0".assume[MinLength[1] & NoNul]), Vec(), Vec())
        )
    case Undef extends Definition(
          SPIRVOpcode.assume("OpUndef"),
          SPIRVOpcodeNumber.assume(1),
          definition =>
            raw =>
              Instruction.decodeDefinition(
                definition,
                raw,
                values => Instruction.Undef(values.required(0), values.required(1))
              ),
          Metadata(
            "Miscellaneous".assume[MinLength[1] & NoNul],
            Some("1.0".assume[MinLength[1] & NoNul]),
            Vec(),
            Vec(
              OperandShape(
                SPIRVOperandKind.assume("IdResultType"),
                "resultType".assume[MinLength[1] & NoNul],
                OperandQuantifier.One
              ),
              OperandShape(
                SPIRVOperandKind.assume("IdResult"),
                "dest".assume[MinLength[1] & NoNul],
                OperandQuantifier.One
              )
            )
          )
        )
    case SourceContinued extends Definition(
          SPIRVOpcode.assume("OpSourceContinued"),
          SPIRVOpcodeNumber.assume(2),
          definition =>
            raw =>
              Instruction.decodeDefinition(definition, raw, values => Instruction.SourceContinued(values.required(0))),
          Metadata(
            "Debug".assume[MinLength[1] & NoNul],
            Some("1.0".assume[MinLength[1] & NoNul]),
            Vec(),
            Vec(OperandShape(
              SPIRVOperandKind.assume("LiteralString"),
              "continuedSrc".assume[MinLength[1] & NoNul],
              OperandQuantifier.One
            ))
          )
        )
    case Source extends Definition(
          SPIRVOpcode.assume("OpSource"),
          SPIRVOpcodeNumber.assume(3),
          definition =>
            raw =>
              Instruction.decodeDefinition(
                definition,
                raw,
                values =>
                  Instruction.Source(values.required(0), values.required(1), values.optional(2), values.optional(3))
              ),
          Metadata(
            "Debug".assume[MinLength[1] & NoNul],
            Some("1.0".assume[MinLength[1] & NoNul]),
            Vec(),
            Vec(
              OperandShape(
                SPIRVOperandKind.assume("SourceLanguage"),
                "sourceLanguage".assume[MinLength[1] & NoNul],
                OperandQuantifier.One
              ),
              OperandShape(
                SPIRVOperandKind.assume("LiteralInteger"),
                "version".assume[MinLength[1] & NoNul],
                OperandQuantifier.One
              ),
              OperandShape(
                SPIRVOperandKind.assume("IdRef"),
                "file".assume[MinLength[1] & NoNul],
                OperandQuantifier.Optional
              ),
              OperandShape(
                SPIRVOperandKind.assume("LiteralString"),
                "src".assume[MinLength[1] & NoNul],
                OperandQuantifier.Optional
